struct Caps {
  int cc;  // compute capability x10, e.g. 860
  // REQUIRED
  bool async_copy;  // global->shared staging whose completion is a signal
  bool tile_load;  // 8x8 b16 quads landed directly in MMA register order
  bool mma_bf16_f32;  // tensor MAC, bf16 operands, fp32 accumulator
  bool bf16_cvt_packed;  // two fp32 -> one b32 of two bf16, one instruction
  bool reg_transpose_b16;  // an 8x8 b16 tile spread across the MMA unit's own registers is transposed IN PLACE. see docs/internals/common/arch_caps.md#reg-transpose-b16
  // RESIDENCY
  bool mma_a_from_regs;  // the A operand may be supplied from the issuing unit's OWN registers. see docs/internals/common/arch_caps.md#mma-a-from-regs
  bool mma_b_from_regs;  // the same for B. A warpgroup MMA sources B ONLY from a shared-memory descriptor. see docs/internals/common/arch_caps.md#mma-b-from-regs
  bool accum_in_tmem;  // the MMA's accumulator lives in a dedicated tensor memory rather than in the unit's register ... see docs/internals/common/arch_caps.md#accum-in-tmem
  bool mma_a_from_tmem;  // the A operand may be sourced from that same tensor memory, which is what lets the invariant ... see docs/internals/common/arch_caps.md#mma-a-from-tmem
  // SELECTING
  bool bf16_simd_arith;  // elementwise bf16 arithmetic on a packed pair (`mul.rn.bf16x2`). see docs/internals/common/arch_caps.md#bf16-simd-arith
  bool bf16_simd_fma;  // FUSED elementwise bf16 arithmetic on a packed pair (`fma.rn.bf16x2`). see docs/internals/common/arch_caps.md#bf16-simd-fma
  bool async_bulk_copy;  // TMA. Would implement `stage_tile`'s contract with one descriptor issue instead of one per ... see docs/internals/common/arch_caps.md#async-bulk-copy
  bool warpgroup_mma;  // `wgmma`. Present on sm_90 and the reason `mma_b_from_regs` is false there. see docs/internals/common/arch_caps.md#warpgroup-mma
  bool dyn_reg_realloc;  // `setmaxnreg`: a warpgroup may GIVE UP or CLAIM registers at run time, so two groups of the ... see docs/internals/common/arch_caps.md#dyn-reg-realloc
  // FACT
  int mma_unit_threads;  // threads that jointly issue one MMA and jointly own its accumulator. 32 (warp) or 128 ... see docs/internals/common/arch_caps.md#mma-unit-threads
  int smem_per_sm;  // `cudaDevAttrMaxSharedMemoryPerMultiprocessor`
  int smem_per_cta_max;  // opt-in dynamic maximum, one CTA
  int smem_granularity;  // shared-memory allocation quantum, bytes
  int regs_per_sm;
  int regs_per_lane_max;
  int reg_alloc_unit;  // registers allocated per warp, in units of this
  int max_threads_per_sm;
  int max_ctas_per_sm;
  int driver_smem_reserve;  // per-CTA reserve the driver takes off the top; the residency condition is on smem_per_cta + ... see docs/internals/common/arch_caps.md#driver-smem-reserve
};

//: THE TABULATED SET -- see docs/internals/common/arch_caps.md#tabulated
constexpr bool tabulated(int cc) {
  return cc == 800 || cc == 860 || cc == 870 || cc == 890 || cc == 900;
}

constexpr Caps caps_of(int cc) {
  if (cc == 800)
    return Caps{.cc = 800, .async_copy = true, .tile_load = true, .mma_bf16_f32 = true, .bf16_cvt_packed = true,
                .reg_transpose_b16 = true, .mma_a_from_regs = true, .mma_b_from_regs = true, .accum_in_tmem = false,
                .mma_a_from_tmem = false, .bf16_simd_arith = false, .bf16_simd_fma = true, .async_bulk_copy = false,
                .warpgroup_mma = false, .dyn_reg_realloc = false, .mma_unit_threads = 32, .smem_per_sm = 167936,
                .smem_per_cta_max = 166912, .smem_granularity = 128, .regs_per_sm = 65536, .regs_per_lane_max = 255,
                .reg_alloc_unit = 256, .max_threads_per_sm = 2048, .max_ctas_per_sm = 32, .driver_smem_reserve = 1024};
  // sm_86: local dev (GA102)
  if (cc == 860)
    return Caps{.cc = 860, .async_copy = true, .tile_load = true, .mma_bf16_f32 = true, .bf16_cvt_packed = true,
                .reg_transpose_b16 = true, .mma_a_from_regs = true, .mma_b_from_regs = true, .accum_in_tmem = false,
                .mma_a_from_tmem = false, .bf16_simd_arith = false, .bf16_simd_fma = true, .async_bulk_copy = false,
                .warpgroup_mma = false, .dyn_reg_realloc = false, .mma_unit_threads = 32, .smem_per_sm = 102400,
                .smem_per_cta_max = 101376, .smem_granularity = 128, .regs_per_sm = 65536, .regs_per_lane_max = 255,
                .reg_alloc_unit = 256, .max_threads_per_sm = 1536, .max_ctas_per_sm = 16, .driver_smem_reserve = 1024};
  if (cc == 870)
    return Caps{.cc = 870, .async_copy = true, .tile_load = true, .mma_bf16_f32 = true, .bf16_cvt_packed = true,
                .reg_transpose_b16 = true, .mma_a_from_regs = true, .mma_b_from_regs = true, .accum_in_tmem = false,
                .mma_a_from_tmem = false, .bf16_simd_arith = false, .bf16_simd_fma = true, .async_bulk_copy = false,
                .warpgroup_mma = false, .dyn_reg_realloc = false, .mma_unit_threads = 32, .smem_per_sm = 167936,
                .smem_per_cta_max = 166912, .smem_granularity = 128, .regs_per_sm = 65536, .regs_per_lane_max = 255,
                .reg_alloc_unit = 256, .max_threads_per_sm = 1536, .max_ctas_per_sm = 16, .driver_smem_reserve = 1024};
  if (cc == 890)
    return Caps{.cc = 890, .async_copy = true, .tile_load = true, .mma_bf16_f32 = true, .bf16_cvt_packed = true,
                .reg_transpose_b16 = true, .mma_a_from_regs = true, .mma_b_from_regs = true, .accum_in_tmem = false,
                .mma_a_from_tmem = false, .bf16_simd_arith = false, .bf16_simd_fma = true, .async_bulk_copy = false,
                .warpgroup_mma = false, .dyn_reg_realloc = false, .mma_unit_threads = 32, .smem_per_sm = 102400,
                .smem_per_cta_max = 101376, .smem_granularity = 128, .regs_per_sm = 65536, .regs_per_lane_max = 255,
                .reg_alloc_unit = 256, .max_threads_per_sm = 1536, .max_ctas_per_sm = 24, .driver_smem_reserve = 1024};
  // sm_90: TABULATED, NOT BUILT; see docs/internals/common/arch_caps.md#caps-of-note-l147
  if (cc == 900)
    return Caps{.cc = 900, .async_copy = true, .tile_load = true, .mma_bf16_f32 = true, .bf16_cvt_packed = true,
                .reg_transpose_b16 = true, .mma_a_from_regs = true, .mma_b_from_regs = false, .accum_in_tmem = false,
                .mma_a_from_tmem = false, .bf16_simd_arith = true, .bf16_simd_fma = true, .async_bulk_copy = true,
                .warpgroup_mma = true, .dyn_reg_realloc = true, .mma_unit_threads = 128, .smem_per_sm = 233472,
                .smem_per_cta_max = 232448, .smem_granularity = 128, .regs_per_sm = 65536, .regs_per_lane_max = 255,
                .reg_alloc_unit = 256, .max_threads_per_sm = 2048, .max_ctas_per_sm = 32, .driver_smem_reserve = 1024};
  return Caps{};
}

//: THE ARCHITECTURE FAMILIES -- see docs/internals/common/hardware.md#families
enum class Family : int { kAmpere, kHopper, kBlackwell };

//: A BUILD: the key a kernel compiles at -- its image's compute capability and its variant (products equal
//: in build traits share one). see docs/internals/common/hardware.md#builds
struct Build {
  int cc;
  int variant;
};

//: A BUILD'S TRAITS: what a kernel's plan reads. see docs/internals/common/hardware.md#traits
struct Traits {
  Family family;
  int window;  // W, a card's: docs/internals/common/window.md
  Caps caps;
};

constexpr Traits traits_of(Build b) {
  if (b.cc == 800 && b.variant == 0)
    return Traits{Family::kAmpere, 1024, caps_of(800)};
  if (b.cc == 860 && b.variant == 0)
    return Traits{Family::kAmpere, 512, caps_of(860)};
  if (b.cc == 870 && b.variant == 0)
    return Traits{Family::kAmpere, 512, caps_of(870)};
  if (b.cc == 890 && b.variant == 0)
    return Traits{Family::kAmpere, 512, caps_of(890)};
  if (b.cc == 900 && b.variant == 0)
    return Traits{Family::kHopper, 0, caps_of(900)};
  return Traits{};
}

//: THE PRODUCTS: a device's product by its name's slug, and the build variant it runs -- see
//: docs/internals/common/hardware.md#products
struct ProductRow {
  int cc;
  const char* slug;
  int variant;
};

inline constexpr ProductRow kProducts[] = {
  {800, "a100", 0},
